using AiTrailTracker.Api.Models;
using AiTrailTracker.Api.Services;
using AiTrailTracker.Api.Storage;

namespace AiTrailTracker.Api.Tests;

public class TeamProgressTests
{
    [Fact]
    public async Task GetTeamProgress_EmptyStorage_ReturnsEmptyList()
    {
        var storage = new InMemoryStorage();
        var svc = new AdminService(storage);

        var result = await svc.GetTeamProgressAsync();
        Assert.Empty(result);
    }

    [Fact]
    public async Task GetTeamProgress_MultipleTeams_GroupsCorrectly()
    {
        var storage = new InMemoryStorage();
        var svc = new AdminService(storage);

        await storage.UpsertParticipantAsync(new Participant
        {
            UserId = "u1", DisplayName = "Alice", Email = "a@test.com",
            Team = "Platform", CurrentLevel = BadgeLevel.Greenhorn,
            CreatedAt = DateTime.UtcNow
        });
        await storage.UpsertParticipantAsync(new Participant
        {
            UserId = "u2", DisplayName = "Bob", Email = "b@test.com",
            Team = "Platform", CurrentLevel = BadgeLevel.Wayfinder,
            CreatedAt = DateTime.UtcNow
        });
        await storage.UpsertParticipantAsync(new Participant
        {
            UserId = "u3", DisplayName = "Carol", Email = "c@test.com",
            Team = "Payments", CurrentLevel = BadgeLevel.TrailGuide,
            CreatedAt = DateTime.UtcNow
        });

        var result = await svc.GetTeamProgressAsync();

        Assert.Equal(2, result.Count);

        var payments = result.Single(t => t.TeamName == "Payments");
        Assert.Equal(1, payments.MemberCount);
        Assert.Equal(1, payments.LevelCounts["TrailGuide"]);

        var platform = result.Single(t => t.TeamName == "Platform");
        Assert.Equal(2, platform.MemberCount);
        Assert.Equal(1, platform.LevelCounts["Greenhorn"]);
        Assert.Equal(1, platform.LevelCounts["Wayfinder"]);
    }

    [Fact]
    public async Task GetTeamProgress_MixedLevels_CorrectLevelCounts()
    {
        var storage = new InMemoryStorage();
        var svc = new AdminService(storage);

        await storage.UpsertParticipantAsync(new Participant
        {
            UserId = "u1", DisplayName = "A", Email = "a@t.com",
            Team = "Core", CurrentLevel = BadgeLevel.Greenhorn, CreatedAt = DateTime.UtcNow
        });
        await storage.UpsertParticipantAsync(new Participant
        {
            UserId = "u2", DisplayName = "B", Email = "b@t.com",
            Team = "Core", CurrentLevel = BadgeLevel.Wayfinder, CreatedAt = DateTime.UtcNow
        });
        await storage.UpsertParticipantAsync(new Participant
        {
            UserId = "u3", DisplayName = "C", Email = "c@t.com",
            Team = "Core", CurrentLevel = BadgeLevel.Pioneer, CreatedAt = DateTime.UtcNow
        });

        var result = await svc.GetTeamProgressAsync();
        var core = result.Single(t => t.TeamName == "Core");

        Assert.Equal(1, core.LevelCounts["Greenhorn"]);
        Assert.Equal(1, core.LevelCounts["Wayfinder"]);
        Assert.Equal(0, core.LevelCounts["TrailGuide"]);
        Assert.Equal(1, core.LevelCounts["Pioneer"]);
    }

    [Fact]
    public async Task GetTeamProgress_StalledParticipant_MarkedAsStalled()
    {
        var storage = new InMemoryStorage();
        var svc = new AdminService(storage);

        // Created 30 days ago, no evidence — should be stalled
        await storage.UpsertParticipantAsync(new Participant
        {
            UserId = "u1", DisplayName = "Stalled User", Email = "s@t.com",
            Team = "Alpha", CurrentLevel = BadgeLevel.Greenhorn,
            CreatedAt = DateTime.UtcNow.AddDays(-30)
        });

        var result = await svc.GetTeamProgressAsync();
        var member = result.Single().Members.Single();

        Assert.True(member.IsStalled);
        Assert.True(member.DaysAtCurrentLevel >= 30);
    }

