    [Fact]
    public async Task GetTeamProgress_UsesLastAdvancementDate_ForDaysAtLevel()
    {
        var storage = new InMemoryStorage();
        var svc = new AdminService(storage);

        await storage.UpsertParticipantAsync(new Participant
        {
            UserId = "u1", DisplayName = "Advanced", Email = "a@t.com",
            Team = "Delta", CurrentLevel = BadgeLevel.Wayfinder,
            CreatedAt = DateTime.UtcNow.AddDays(-60),
            LastAdvancementAt = DateTime.UtcNow.AddDays(-5)
        });

        var result = await svc.GetTeamProgressAsync();
        var member = result.Single().Members.Single();

        // Should be ~5 days, not 60
        Assert.True(member.DaysAtCurrentLevel >= 5);
        Assert.True(member.DaysAtCurrentLevel < 10);
    }
